async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
    if scope["type"] != "http":
        await self.app(scope, receive, send)
        return

    response_started = False

    async def _send(message: Message) -> None:
        nonlocal response_started, send

        if message["type"] == "http.response.start":
            response_started = True
        await send(message)

    try:
        await self.app(scope, receive, _send)
    except Exception as exc:
        request = Request(scope)
        if self.debug:
            # In debug mode, return traceback responses.
            response = await run_in_threadpool(self.debug_response, request, exc)
        elif self.handler is None:
            # Use our default 500 error handler.
            response = self.error_response(request, exc)
        else:
            # Use an installed 500 error handler.
            if is_async_callable(self.handler):
                response = await self.handler(request, exc)  # type: ignore[assignment, arg-type]
            else:
                response = await run_in_threadpool(self.handler, request, exc)  # type: ignore[arg-type]

        if not response_started:
            await response(scope, receive, send)

        # We always continue to raise the exception.
        # This allows servers to log the error, or allows test clients
        # to optionally raise the error within the test case.
        raise exc

async def __call__(self) -> None:
    if self.is_async:
        await self.func(*self.args, **self.kwargs)
    else:
        await run_in_threadpool(self.func, *self.args, **self.kwargs)

async def run_in_threadpool(func: Callable[P, T], *args: P.args, **kwargs: P.kwargs) -> T:
    func = functools.partial(func, *args, **kwargs)
    return await anyio.to_thread.run_sync(func)

def add_task(self, func: Callable[P, Any], *args: P.args, **kwargs: P.kwargs) -> None:
    task = BackgroundTask(func, *args, **kwargs)
    self.tasks.append(task)

async def __call__(self) -> None:
    for task in self.tasks:
        await task()

def is_async_callable(obj: Any) -> Any:
    while isinstance(obj, functools.partial):
        obj = obj.func

    return iscoroutinefunction(obj) or (callable(obj) and iscoroutinefunction(obj.__call__))

void ttlGenericCommand(client *c, int output_ms, int output_abs) {
    long long expire, ttl = -1;

    /* If the key does not exist at all, return -2 */
    kvobj *kv = lookupKeyReadWithFlags(c->db,c->argv[1],LOOKUP_NOTOUCH);
    if (kv == NULL) {
        addReplyLongLong(c,-2);
        return;
    }

    /* The key exists. Return -1 if it has no expire, or the actual
     * TTL value otherwise. */
    expire = kvobjGetExpire(kv);
    if (expire != -1) {
        ttl = output_abs ? expire : expire-commandTimeSnapshot();
        if (ttl < 0) ttl = 0;
    }
    if (ttl == -1) {
        addReplyLongLong(c,-1);
    } else {
        addReplyLongLong(c,output_ms ? ttl : ((ttl+500)/1000));
    }
}

